<?php
declare(strict_types=1);
if (!defined('ACADEMY_ROOT')) { http_response_code(403); exit; }

// Educational adaptation of the supplied Sales Training Manual, not certification.
function academy_manual_lesson(string $title,string $goal,array $sections,array $scenario,array $quiz,int $minutes=9): array
{
    return ['title'=>$title,'goal'=>$goal,'sections'=>$sections,'scenario'=>$scenario,'quiz'=>$quiz,'minutes'=>$minutes,'version'=>1];
}
function academy_manual_lessons(): array
{
    return [
    'me-pv-basics'=>academy_manual_lesson('Φωτοβολταϊκά: από το panel στο δίκτυο','Να ξεχωρίζεις ισχύ, ενέργεια, βασικό εξοπλισμό και τεχνικά όρια.',[
        ['Η διαδρομή της ενέργειας',['Κυψέλες → module/panel → string → inverter → ηλεκτρικός εξοπλισμός και δίκτυο. Τα panels παράγουν συνεχές ρεύμα (DC). Ο inverter το μετατρέπει σε εναλλασσόμενο (AC).','Watt, kW και MW μετρούν ισχύ: 1 kW = 1.000 W, 1 MW = 1.000 kW. kWh και MWh μετρούν ενέργεια. MWp είναι ονομαστική ισχύς στις συνθήκες αναφοράς, όχι εγγυημένη παραγωγή.']],
        ['Τι υπάρχει στο πάρκο',['Βάσεις, strings, καλώδια/connectors, inverters, προστασίες, μετασχηματιστής, monitoring/SCADA, περίφραξη, πρόσβαση και αποστράγγιση. Fixed tilt: σταθερές βάσεις. Tracker: κινούμενες βάσεις με πρόσθετες ανάγκες συντήρησης.','Mono/poly περιγράφουν τεχνολογίες κυψελών. PERC, TOPCon και HJT είναι διαφορετικές τεχνολογικές προσεγγίσεις. Bifacial αξιοποιεί και πίσω ακτινοβολία. Glass-glass αφορά κατασκευή με γυαλί και στις δύο πλευρές. Δεν είναι όλοι αυτοί οι όροι εναλλακτικές της ίδιας κατηγορίας.']],
        ['Label, απόδοση και έλεγχοι',['Pmax: μέγιστη ονομαστική ισχύς. Voc/Isc: τάση ανοικτού κυκλώματος/ρεύμα βραχυκυκλώματος. Vmp/Imp: τάση/ρεύμα στο σημείο μέγιστης ισχύος. Καταγράφουμε κατασκευαστή, μοντέλο και serial.','Σκιάσεις, soiling, υψηλή θερμοκρασία, degradation και βλάβες επηρεάζουν παραγωγή. Monitoring και Performance Ratio βοηθούν την τεχνική ομάδα να αξιολογεί λειτουργία. Δεν δίνουμε διάγνωση ή εγγύηση από έναν αριθμό.','Visual inspection, θερμογραφία, I-V curve, insulation test, EL test και flash test εξυπηρετούν διαφορετικούς ελέγχους. Οι ηλεκτρικές δοκιμές γίνονται από αρμόδιους, όχι από τον πωλητή.']]
    ],['«Το panel είναι 300 W, άρα παράγει 300 kWh;»','Όχι. Τα Watt είναι ισχύς, οι kWh ενέργεια σε χρόνο. Καταγράφεις το ερώτημα και ζητάς τεχνική εκτίμηση παραγωγής.'],[
        ['Τι κάνει ο inverter;',['Μετατρέπει DC σε AC','Καθαρίζει panels','Μετρά τη commission'],0,'Ο inverter μετατρέπει το συνεχές ρεύμα των panels.'],
        ['Ποια μονάδα μετρά ενέργεια;',['MWp','Watt','kWh'],2,'Η kWh είναι μονάδα ενέργειας.'],
        ['Ο πωλητής βλέπει alarm inverter. Τι κάνει;',['Υπόσχεται συγκεκριμένη βλάβη','Καταγράφει στοιχεία και ζητά τεχνική αξιολόγηση','Ανοίγει τον ηλεκτρικό πίνακα'],1,'Αναγνωρίζει την ανάγκη, δεν αναλαμβάνει τεχνική διάγνωση.']
    ],12),
    'me-panel-inspection'=>academy_manual_lesson('Μεταχειρισμένα panels: κατάσταση & testing','Να συλλέγεις αποδείξεις για το lot, όχι μόνο μια περιγραφή «είναι καλά».',[
        ['Τι ζητάμε',['Ποσότητα, Watt, μάρκα/μοντέλο, έτος όπου είναι γνωστό, φωτογραφίες μπροστά/πίσω, καθαρό label, κοντινά ελαττωμάτων, παλέτες/εγκατάσταση και serial list όταν υπάρχει.','Mixed stock σημαίνει διαφορετικά μοντέλα, Watt ή έτη. Χρειάζεται sorting και αξιολόγηση ανά κατηγορία, όχι ενιαία υπόθεση ποιότητας.']],
        ['Σημάδια που καταγράφουμε',['Cracked glass, burn marks, cracked backsheet, υγρασία/διάβρωση, delamination, στραβό frame, χαλαρό junction box, κομμένα καλώδια και σπασμένοι connectors χρειάζονται ειδική αξιολόγηση.','Yellowing/browning και snail trails είναι ενδείξεις προς διερεύνηση. Microcracks μπορεί να μην είναι ορατά. Δεν βαφτίζουμε κάθε σημάδι οριστική αστοχία ούτε το αποκρύπτουμε.']],
        ['«Tested» δεν αρκεί',['Ρωτάμε ποιο test, πότε, από ποιον, με ποια κάλυψη και αν υπάρχει report ανά serial. Flash test ελέγχει ισχύ, EL μπορεί να αναδείξει εσωτερικές ρωγμές, θερμογραφία θερμικές ανωμαλίες.','300 W μετρημένα στα 276 W σημαίνει 92% της ονομαστικής ισχύος. Δεν σημαίνει αυτόματα αποδοχή: τα thresholds κρίνονται ανά deal. Ζητάμε αντιπροσωπευτικό sample, όχι μόνο 2–3 επιλεγμένα καλά panels.']]
    ],['Ο seller στέλνει φωτογραφίες δύο καλών panels για lot 5.000.','Ζητάς αντιπροσωπευτικά στοιχεία, κατανομή μοντέλων/κατάστασης και τεκμηρίωση testing. Δεν θεωρείς το δείγμα απόδειξη για όλο το lot.'],[
        ['276 W από ονομαστικά 300 W είναι…',['92%','76%','Αυτόματη έγκριση αγοράς'],0,'276 / 300 = 0,92· η αποδοχή είναι άλλη απόφαση.'],
        ['Τι ρωτάμε στο «tested»;',['Μόνο την τιμή','Test, ημερομηνία, φορέα, reports και δείγμα','Τίποτε άλλο'],1,'Η δήλωση χρειάζεται τεκμηρίωση.'],
        ['Δύο καλά panels αποδεικνύουν την ποιότητα 5.000;',['Ναι','Μόνο αν είναι ίδια μάρκα','Όχι, χρειάζεται αντιπροσωπευτικός έλεγχος'],2,'Αποφεύγουμε το cherry-picking.']
    ]),
    'me-panel-logistics'=>academy_manual_lesson('Logistics, landed cost & οι πέντε πύλες αγοράς','Να εντοπίζεις κόστος και ρίσκο μέχρι την πραγματική παραλαβή.',[
        ['Δεν αγοράζουμε μόνο Watt',['Καταγράφουμε μήκος × πλάτος × πάχος, βάρος, frame, παλέτες, στοίβαξη και χώρο container. Παχύτερο frame ή μεγαλύτερο βάρος μπορεί να αυξάνει κόστος ανά τεμάχιο.','Τιμή αγοράς + φόρτωση + εργασία + forklift + οδική μεταφορά + container/shipping + handling + testing/sorting + πρόβλεψη ελαττωματικών = συνολική εικόνα κόστους.']],
        ['Ερωτήσεις παραλαβής',['Είναι ακόμη εγκατεστημένα; Ποιος αποξηλώνει; Ποιος φορτώνει; Υπάρχει forklift; Πρόσβαση φορτηγού; Συσκευασία; Ημερομηνία διαθεσιμότητας; Ποιο ποσοστό είναι damaged;','Κακό dismantling μπορεί να καταστρέψει frame, καλώδια και connectors. EXW στο εγχειρίδιο υπενθυμίζει ανάγκη οργάνωσης παραλαβής· οι ακριβείς συμβατικοί όροι εγκρίνονται από την αρμόδια ομάδα.']],
        ['Πέντε πύλες',['Ταυτότητα/δικαίωμα πώλησης → κατάσταση → απόδοση/testing → logistics → πραγματική δεύτερη χρήση/εμπορική αξία.','ΠΑΝΕΛ: Ποσότητα · Απόδοση/Αποξήλωση · Νομιμότητα/οργάνωση stock · Ελαττώματα · Logistics. Green: σαφής seller και οργανωμένο lot. Yellow: άγνωστο testing ή mixed stock. Red: σοβαρές ζημιές ή ασαφές δικαίωμα πώλησης.']]
    ],['Φθηνότερο panel αλλά διπλάσιο μεταφορικό κόστος ανά τεμάχιο.','Συγκρίνεις συνολικό κόστος παραλαβής και ποιότητα, όχι μόνο τη ζητούμενη τιμή. Ζητάς έγκριση πριν δεσμεύσεις αγορά.'],[
        ['Landed cost σημαίνει…',['Μόνο asking price','Συνολικό κόστος αγοράς και παραλαβής','Μόνο shipping'],1,'Η σύγκριση περιλαμβάνει όλα τα σχετικά κόστη.'],
        ['Άγνωστος seller χωρίς δικαίωμα πώλησης είναι…',['Red flag','Έτοιμο qualified lead','Λόγος να δώσουμε προκαταβολή'],0,'Η ταυτότητα και η εξουσιοδότηση προηγούνται.'],
        ['Το frame επηρεάζει…',['Μόνο το χρώμα','Μόνο το quiz','Βάρος, στοίβαξη και κόστος logistics'],2,'Η φυσική μορφή επηρεάζει τη μεταφορά.']
    ]),
    'me-construction'=>academy_manual_lesson('Υπηρεσίες 01–05: από τον χώρο στην κατασκευή','Να εντοπίζεις στάδιο, scope και υπεύθυνο χωρίς τεχνικές δεσμεύσεις.',[
        ['01 & 02: χώρος και σχεδιασμός',['01: θέση, έκταση, κλίση, σκιάσεις, πρόσβαση, έδαφος και κατάσταση προηγούμενων ελέγχων. Δεν δηλώνουμε μόνοι μας ότι ένας χώρος είναι κατάλληλος.','02: ποιες μελέτες/εγκρίσεις υπάρχουν, πού έχει κολλήσει το έργο, στόχος ημερομηνίας και υπεύθυνος. Δεν δίνουμε νομική ή αδειοδοτική διαβεβαίωση.']],
        ['03 & 04: προετοιμασία και εξοπλισμός',['03: βλάστηση, χωματουργικά, δρόμοι, περίφραξη και αποστράγγιση. Ρωτάμε τι έχει ήδη ανατεθεί και πότε πρέπει να ολοκληρωθεί.','04: panels, βάσεις, inverters, καλώδια και εξοπλισμός. Ζητάμε BoQ, εκκρεμές procurement, παράδοση και ανάγκες συνεργείων. Δεν υποσχόμαστε τιμή ή διαθεσιμότητα.']],
        ['05: ηλεκτρολογικό scope',['DC/AC συνδέσεις, γειώσεις, πίνακες, προστασίες, transformer, testing και commissioning. Ποιο scope μένει; Χρειάζεται δεύτερο crew; Ποιο χρονοδιάγραμμα έχει εγκριθεί;','Το commissioning είναι τελικός τεχνικός έλεγχος πριν την κανονική λειτουργία, όχι οικονομική προμήθεια. Η τεχνική ομάδα εγκρίνει λύση, συνεργείο και χρόνο.']]
    ],['Project Manager ζητά δεύτερο ηλεκτρολογικό συνεργείο σε τρεις εβδομάδες.','Συλλέγεις συγκεκριμένο scope, site, μέγεθος, timing και αρμόδιο. Οργανώνεις τεχνικό meeting χωρίς υπόσχεση διαθεσιμότητας.'],[
        ['BoQ σημαίνει…',['Λίστα υλικών/ποσοτήτων','Εγγύηση κέρδους','Λίστα προμηθειών συνεργάτη'],0,'Το BoQ τεκμηριώνει το αντικείμενο προμήθειας.'],
        ['Ποιος εγκρίνει τεχνικό κόστος και χρονοδιάγραμμα;',['Ο νέος πωλητής','Η αρμόδια εξουσιοδοτημένη ομάδα','Οποιοσδήποτε χρήστης CRM'],1,'Η συλλογή στοιχείων δεν είναι εξουσιοδότηση.'],
        ['Commissioning είναι…',['Το 8% της αμοιβής','Πληρωμή πωλητή','Τεχνικός έλεγχος πριν την κανονική λειτουργία'],2,'Δεν συγχέουμε commissioning και commission.']
    ]),
    'me-operations'=>academy_manual_lesson('Υπηρεσίες 06–09: λειτουργία, απόδοση & repowering','Να αναγνωρίζεις επαναλαμβανόμενες ανάγκες και συνδεδεμένες ευκαιρίες.',[
        ['Συντήρηση και καθαρισμός',['06: preventive maintenance πριν το πρόβλημα, corrective μετά τη βλάβη. Ρωτάμε για O&M contract, recurring faults, response time και ανάγκη backup provider.','07: soiling, βλάστηση, πρόσβαση και πρόγραμμα φροντίδας. Πόσα πάρκα; Πότε τελευταίος/επόμενος καθαρισμός; Καλύπτει ο ίδιος provider όλες τις περιοχές; Δεν υπάρχει καθολικό διάστημα καθαρισμού για κάθε πάρκο.']],
        ['Απόδοση και αντικατάσταση',['08: performance check και repowering. Γιατί γίνεται; Τι εξοπλισμός αλλάζει; Ποιος contractor; Πότε; Υπάρχει νέο equipment;','09: αντικατάσταση λόγω βλάβης, αναβάθμισης, καιρικού συμβάντος ή warranty. Πόσα panels, ποια μοντέλα, ποιος αποξηλώνει και τι γίνεται το αφαιρούμενο stock;']],
        ['Μακροχρόνια συνεργασία',['Maintenance → repair → performance → repowering → replacement → παλιά panels → επόμενο maintenance/cleaning. Κάθε ευκαιρία τεκμηριώνεται χωριστά.','Η ύπαρξη συνεργάτη δεν αποδεικνύει ούτε έλλειψη ευκαιρίας ούτε αυτόματα ανάγκη αλλαγής. Ρωτάμε με σεβασμό για έκτακτα, γεωγραφική κάλυψη και peak load.']]
    ],['Ακούς «κάνουμε repowering». Ποια πρόσθετη ερώτηση θέτεις;','«Τι θα γίνει με τα παλιά panels;» Διερευνάς ξεχωριστά την υπηρεσία και πιθανή αγορά εξοπλισμού.'],[
        ['Preventive maintenance γίνεται…',['Μόνο μετά από βλάβη','Για πρόληψη προβλημάτων','Μόνο μετά από πώληση'],1,'Η προληπτική συντήρηση προηγείται της αστοχίας.'],
        ['Υπάρχων O&M provider σημαίνει…',['Ποτέ καμία άλλη ανάγκη','Αυτόματα qualified lead','Χρειάζεται διερεύνηση κάλυψης και συγκεκριμένης ανάγκης'],2,'Δεν συμπεραίνουμε χωρίς discovery.'],
        ['Ποια διπλή ευκαιρία μπορεί να δώσει repowering;',['Υπηρεσίες και αγορά παλιών panels','Διπλό €80 χωρίς έλεγχο','Αυτόματη αλλαγή ιδιοκτήτη lead'],0,'Τα αντικείμενα αξιολογούνται χωριστά.']
    ]),
    'me-special-services'=>academy_manual_lesson('Πάρκα προς πώληση & οικιακά φωτοβολταϊκά','Να χειρίζεσαι ευκαιρίες 10–11 χωρίς ανεπιβεβαίωτες υποσχέσεις.',[
        ['10: το πάρκο ως asset',['Αρμόδιος owner/εξουσιοδοτημένος εκπρόσωπος, πραγματική πρόθεση, θέση, MW, operating/development, έτος, εξοπλισμός και ζητούμενη τιμή. Έσοδα, κόστη, γη και χρηματοδότηση μόνο όπου επιτρέπεται.','Due diligence: τεχνικός, οικονομικός, νομικός και φορολογικός έλεγχος από ειδικούς. Data Room: οργανωμένο σύνολο σχετικών στοιχείων με ελεγχόμενη πρόσβαση. Ο πωλητής δεν πιστοποιεί μόνος του την επένδυση.']],
        ['Η σωστή βάση του 12%',['Αξία πάρκου €2.000.000 και πραγματική αμοιβή MELAS €40.000: βάση είναι η εγκεκριμένη αμοιβή MELAS, όχι τα €2.000.000. Σε πλήρη επιλέξιμη είσπραξη: €40.000 × 12% = €4.800.','Η έγκριση του lead δίνει χωριστά €80. Μια φήμη για πώληση δεν αποτελεί qualified lead.']],
        ['11: σπίτι και αυτοκατανάλωση',['Συλλέγουμε περιοχή/ακίνητο, στέγη/χώρο, σκιάσεις, φωτογραφίες, κατανάλωση από πρόσφατους λογαριασμούς, ενδιαφέρον για αποθήκευση και timing.','Δεν υποσχόμαστε ακριβή kW, μηδενικό λογαριασμό, διάρκεια μπαταρίας, απόδοση επένδυσης ή επιδότηση χωρίς αξιολόγηση. Εσωτερικό rate υπηρεσίας 11: 7% στην εγκεκριμένη επιλέξιμη βάση.']]
    ],['Πάρκο €2 εκατ. με αμοιβή MELAS €40.000. Ποια βάση διαλέγεις;','Την εγκεκριμένη αμοιβή των €40.000 και μόνο το επιλέξιμο μέρος που πράγματι εισπράχθηκε.'],[
        ['Το 12% της υπηρεσίας 10 εφαρμόζεται…',['Στην αξία πάρκου','Στην επιλέξιμη αμοιβή MELAS','Στα MW'],1,'Η αξία του asset δεν είναι έσοδο MELAS.'],
        ['€40.000 × 12% ισούται με…',['€4.800','€240.000','€400'],0,'Ο υπολογισμός αφορά την αμοιβή MELAS.'],
        ['Σε οικιακό έργο υπόσχεσαι μηδενικό λογαριασμό;',['Ναι','Αν υπάρχει μπαταρία','Όχι χωρίς εγκεκριμένη τεχνική/οικονομική ανάλυση'],2,'Η συλλογή στοιχείων προηγείται οποιασδήποτε δέσμευσης.']
    ]),
    'me-research'=>academy_manual_lesson('Prospecting, triggers & σωστός άνθρωπος','Να μετατρέπεις την έρευνα σε συγκεκριμένο λόγο επαφής.',[
        ['Πριν ψάξεις, όρισε στόχο',['Panels προς αγορά, cleaning, O&M, EPC subcontracting, repowering ή park transaction; Ο στόχος καθορίζει πηγές και ρόλους.','Owners, asset managers, O&M, EPC, developers, contractors, installers και traders δεν έχουν την ίδια ανάγκη. Χρησιμοποίησε δημόσια εταιρικά websites, projects/news, LinkedIn, κλαδικές πηγές και εκθέσεις.']],
        ['Trigger thinking',['Ανακοίνωση repowering → υπηρεσίες και πιθανό old stock. Αγορά portfolio → πιθανές ανάγκες λειτουργίας. Νέο έργο → υπηρεσίες 01–05. Πρόσληψη τεχνικών → υπόθεση ανάπτυξης, όχι απόδειξη ανάγκης.','Cleaning: O&M Manager. Repowering: Technical/Asset Manager. EPC: Project/Construction Manager. Πώληση πάρκου: Owner/Investment Manager. Δεν κυνηγάμε πάντα CEO.']],
        ['Research card',['Εταιρεία, χώρα, website, τύπος/δραστηριότητα, projects/MW, contact/θέση, στοιχεία επαφής, trigger, πιθανή υπηρεσία, πηγή και ημερομηνία.','Research → fit → trigger → decision maker → sales angle → πραγματική συζήτηση → πιθανό qualified lead. Priority A/B/C στην έρευνα δεν ισοδυναμεί με έγκριση €80.']]
    ],['Βρίσκεις ότι μια εταιρεία προσέλαβε 10 τεχνικούς.','Το κρατάς ως ερευνητική ένδειξη. Ρωτάς για έργα και ανάγκες, χωρίς να κατασκευάζεις qualified lead.'],[
        ['Ένα trigger είναι…',['Εγγυημένη πώληση','Ένδειξη για στοχευμένη διερεύνηση','Έγκριση commission'],1,'Επιβεβαιώνεται με πραγματική επαφή.'],
        ['Για cleaning αναζητάς συχνά…',['Τον O&M υπεύθυνο','Μόνο CEO','Οποιοδήποτε info@'],0,'Ο κατάλληλος ρόλος εξαρτάται από το αντικείμενο.'],
        ['Prospect γίνεται qualified…',['Με την εύρεση website','Με ένα μαζικό email','Με επιβεβαιωμένη ανάγκη και εσωτερική έγκριση'],2,'Research δεν είναι qualification.']
    ]),
    'me-discovery'=>academy_manual_lesson('Discovery: επτά κατηγορίες ουσιαστικών ερωτήσεων','Να ακούς, να επιβεβαιώνεις και να συμφωνείς επόμενο βήμα.',[
        ['Οι επτά κατηγορίες',['Ανάγκη · γιατί τώρα · μέγεθος · χρόνος · απόφαση · σημερινή λύση · επόμενο βήμα. Δεν συμπληρώνουμε μηχανικά ένα ερωτηματολόγιο: ακολουθούμε τη συζήτηση.','Ανοιχτή ερώτηση: «Πώς οργανώνετε τη συντήρηση;» Κλειστή: «Έχετε O&M contract;» Επιβεβαίωση: «Άρα το πρόβλημα αφορά δύο sites και τον επόμενο μήνα;»']],
        ['Ειδικά για κάθε ευκαιρία',['Panels: quantity/Watt/model, mixed stock, λόγος αφαίρεσης, εγκατεστημένα ή αποξηλωμένα, timing, location, κατάσταση/testing, buyer και decision maker.','O&M: parks/MW, in-house/outsourced, faults, response time, γεωγραφικά κενά και ανανέωση συμβολαίου. Repowering: equipment, contractor, νέο stock και παλιά panels.']],
        ['Από την ανάγκη στην απόφαση',['Ποιοι συμμετέχουν; Procurement/tender; Ποια κριτήρια; Budget ή φάση προσφορών; Μέχρι πότε; Τι συμβαίνει αν δεν λυθεί; Δεν εφευρίσκουμε urgency.','ΡΩΤΑ → ΑΚΟΥ → ΚΑΤΑΛΑΒΕ → ΕΠΙΒΕΒΑΙΩΣΕ → ΠΡΟΧΩΡΑ. Μία ερώτηση κάθε φορά, ενεργητική ακρόαση και σύντομη τελική σύνοψη.']]
    ],['Ο πελάτης λέει «χρειαζόμαστε καλύτερη απόδοση».','Ρωτάς τι παρατηρεί, σε ποια sites, από πότε, τι έχει ελεγχθεί και ποιος αξιολογεί. Δεν διαγιγνώσκεις ότι χρειάζεται repowering.'],[
        ['Discovery προηγείται…',['Της πρότασης λύσης','Μόνο του logout','Μόνο της τιμολόγησης'],0,'Πρώτα καταλαβαίνουμε την ανάγκη.'],
        ['Στο «έχουμε πρόβλημα» απαντάς…',['«Χρειάζεστε νέα panels»','«Πείτε μου περισσότερα: πού, από πότε, τι επίπτωση έχει;»','«Είναι σίγουρα inverter»'],1,'Ρωτάμε πριν διαγνώσουμε.'],
        ['Η σωστή σύνοψη περιλαμβάνει…',['Μόνο τιμή','Μόνο το όνομα','Ανάγκη, timing, αρμόδιο και συμφωνημένο next step'],2,'Η συμφωνία επόμενου βήματος δημιουργεί συνέχεια.']
    ]),
    'me-objections'=>academy_manual_lesson('Αντιρρήσεις χωρίς πίεση','Να καταλαβαίνεις το εμπόδιο και να σέβεσαι το σαφές όχι.',[
        ['ΑΡΑ: Ακούω → Ρωτάω → Απαντάω',['Ακούω μέχρι τέλος, αναγνωρίζω, κάνω μία σχετική ερώτηση, ακούω την αιτία και απαντώ μόνο σε αυτή. Η αντίρρηση είναι πληροφορία, όχι μάχη.','One Extra Question: μία καλή διευκρίνιση όπου υπάρχει διάθεση, όχι δέκα. Σε σαφές αίτημα διακοπής, σταματάμε και καταγράφουμε την προτίμηση.']],
        ['Συνηθισμένες απαντήσεις',['«Έχουμε συνεργάτη/ομάδα»: καλύπτονται όλες οι περιοχές, τα έκτακτα και το peak load; «Στείλτε email»: τι είναι σχετικό και πότε συμφωνούμε follow-up; «Δεν έχω χρόνο»: υπάρχει καλύτερη συγκεκριμένη ώρα;','«Πόσο δίνετε;»: πρώτα quantity, Watt/model, condition, location και logistics. «Είστε ακριβοί»: συγκρίνουμε ίδιο scope και όρους; «Έχουμε buyer»: έχει οριστικοποιηθεί η συμφωνία;']],
        ['Όρια και επαγγελματισμός',['NDA/νομικές αλλαγές πάνε στον αρμόδιο. Τεχνικά ζητήματα στην τεχνική ομάδα. Δεν δυσφημίζουμε ανταγωνιστές, δεν πιέζουμε για εμπιστευτικές πληροφορίες, δεν εφευρίσκουμε έκπτωση.','«Αν λυνόταν αυτό το θέμα, υπάρχει κάτι άλλο που θα εμπόδιζε το επόμενο βήμα;» Η απάντηση δεν αποτελεί άδεια για παραχώρηση.']]
    ],['«Δεν θέλω άλλη επικοινωνία».','Σταματάς ευγενικά και καταγράφεις το αίτημα. Δεν το αντιμετωπίζεις ως άσκηση επιμονής.'],[
        ['Μετά από σαφές αίτημα διακοπής…',['Επιμένω άλλη μία φορά','Σέβομαι και καταγράφω','Αλλάζω τηλέφωνο'],1,'Η δεοντολογία υπερισχύει του στόχου κλήσεων.'],
        ['Στο «είστε ακριβοί» εξετάζω…',['Ίδιο scope, όρους και πραγματικό εμπόδιο','Άμεση αυθαίρετη έκπτωση','Πώς θα δυσφημίσω άλλον'],0,'Πρώτα καταλαβαίνουμε τη σύγκριση.'],
        ['One Extra Question σημαίνει…',['Δέκα πιεστικές ερωτήσεις','Καμία ακρόαση','Μία σχετική διευκρίνιση όταν υπάρχει διάθεση'],2,'Η διευκρίνιση δεν παραβιάζει το όχι.']
    ]),
    'me-negotiation'=>academy_manual_lesson('Negotiation & closing: δεν χαρίζουμε, ανταλλάσσουμε','Να ζητάς πραγματικό επόμενο βήμα μέσα στην εξουσιοδότησή σου.',[
        ['Micro-closes',['Data, meeting, site visit, scope, offer, terms και PO/contract είναι διαφορετικά μικρά κλεισίματα. Δεν ζητάμε την τελική αγορά σε κάθε στάδιο.','Buying signals: ερωτήσεις για έναρξη, ομάδα, πληρωμή και επόμενα δικαιολογητικά. Trial close: «Μέχρι εδώ σας καλύπτει η λύση;» Δεν σημαίνει ακόμη WON.']],
        ['Give & Get',['Πιθανή παραχώρηση συνδέεται με συγκεκριμένη ανταπόδοση: ποσότητα, διάρκεια, sites ή δέσμευση. Πάντα απαιτείται αρμόδια έγκριση.','Δεν μειώνουμε μόνοι μας τιμή επειδή ο πελάτης σιώπησε. Ρωτάμε αν συγκρίνονται ίδια scope/όροι και αν η τιμή είναι το μόνο εμπόδιο.']],
        ['Κλείσιμο με καθαρούς όρους',['Panels: τεκμηριωμένα condition, age, uniformity, testing και logistics, όχι επινοημένα defects. Walk-away: δεν χρειάζεται να κλείσουμε μη βιώσιμο deal.','Μετά το verbal yes ζητάμε κατάλληλη γραπτή επιβεβαίωση, PO ή σύμβαση. Δεν παρακάμπτουμε εμπορική έγκριση ή CEO approval για υπογραφή.']]
    ],['Ο πελάτης ζητά 15% έκπτωση για να «το σκεφτεί».','Διερευνάς το πραγματικό εμπόδιο και την ανταπόδοση. Μεταφέρεις αίτημα στην αρμόδια ομάδα χωρίς να εγκρίνεις μόνος σου έκπτωση.'],[
        ['Closing είναι…',['Πίεση μέχρι να πει ναι','Σαφές επόμενο πραγματικό βήμα','Αυτόματη εξόφληση'],1,'Υπάρχουν πολλά μικρά κλεισίματα.'],
        ['Give & Get απαιτεί…',['Εγκεκριμένη παραχώρηση με συγκεκριμένη ανταπόδοση','Δωρεάν έκπτωση πάντα','Υπόσχεση χωρίς scope'],0,'Δεν χαρίζουμε αξία χωρίς έγκριση.'],
        ['Το verbal yes ακολουθεί…',['Αυτόματη commission υπηρεσίας','Διαγραφή follow-up','Κατάλληλη γραπτή επιβεβαίωση και εγκεκριμένοι όροι'],2,'Προφορικό ενδιαφέρον δεν είναι πραγματική είσπραξη.']
    ]),
    'me-written'=>academy_manual_lesson('Email, LinkedIn & follow-up με συγκεκριμένο σκοπό','Να γράφεις σύντομα και να κρατάς τις συμφωνημένες ενέργειες.',[
        ['Η δομή ενός μηνύματος',['Χαιρετισμός → ποιοι είμαστε σε μία πρόταση → συγκεκριμένος λόγος → σχετική ερώτηση → σαφές next step. Όχι τεράστια παρουσίαση, clickbait subject ή ανεπιθύμητα attachments.','Στο follow-up αναφέρουμε το προηγούμενο context και τι υποσχεθήκαμε, όχι επανάληψη ολόκληρου pitch. LinkedIn βοηθά στο research και στη σχετική επαφή, όχι σε spam.']],
        ['Κάθε επόμενο βήμα έχει ημερομηνία',['Μετά το cold call: στέλνω ό,τι συμφωνήθηκε. Μετά offer: επιβεβαιώνω παραλαβή και review date. Μετά meeting: σύνοψη και agreed actions.','Future project δεν σημαίνει αναμονή ως την ημερομηνία κατασκευής. Μαθαίνουμε πότε επιλέγεται vendor και συμφωνούμε follow-up νωρίτερα.']],
        ['Καθαρή καταγραφή',['HOT: πραγματική ανάγκη και κοντινό timing. WARM: ουσιαστική πιθανότητα όχι άμεσα. COLD: χωρίς συγκεκριμένη ανάγκη. Δεν αλλάζουμε κατηγορία μόνο για καλύτερους αριθμούς.','Κάθε ανοικτή ευκαιρία: next step, ημερομηνία, owner και σημείωση. Σε LOST καταγράφουμε συγκεκριμένη αιτία. Σε μελλοντικό έργο καταγράφουμε γιατί περιμένουμε.']]
    ],['Έργο ξεκινά σε τέσσερις μήνες. Πότε ξαναμιλάς;','Ρωτάς πότε επιλέγεται συνεργάτης και κλείνεις συγκεκριμένη νωρίτερη ημερομηνία, όχι αυθαίρετη υπενθύμιση την ημέρα έναρξης.'],[
        ['Καλό πρώτο email είναι…',['Μακρύ και γενικό','Σύντομο, σχετικό, με ερώτηση και next step','Μόνο συνημμένα'],1,'Το context έχει μεγαλύτερη αξία από τον όγκο.'],
        ['Follow-up για future project…',['Συμφωνείται με βάση τον χρόνο επιλογής συνεργάτη','Γίνεται μόνο όταν ξεκινήσει','Δεν χρειάζεται'],0,'Η εμπορική απόφαση συνήθως προηγείται.'],
        ['Open opportunity χωρίς ημερομηνία…',['Είναι ολοκληρωμένη','Είναι αυτόματα LOST','Χρειάζεται συμπλήρωση επόμενου βήματος'],2,'Η αόριστη αναμονή δεν είναι πλάνο.']
    ]),
    'me-account-growth'=>academy_manual_lesson('KPIs, recurring business & ανάπτυξη λογαριασμού','Να μετράς ποιότητα και να χτίζεις σχέση πέρα από μία πώληση.',[
        ['Μετράμε μετατροπές, όχι μόνο κλήσεις',['Prospects, σωστοί decision makers, ουσιαστικές συζητήσεις, qualified leads, meetings, offers, negotiations, won deals και συνέπεια follow-up.','100 prospects → 20 συζητήσεις → 5 qualified: 20% prospect-to-discussion, 25% discussion-to-qualified, 5% συνολικά. Χαμηλή μετατροπή απαιτεί διερεύνηση targeting, ποιότητας ή συνέχειας.']],
        ['Καθημερινή σειρά',['HOT leads και υποσχέσεις → σημερινά follow-ups → νέο research → νέες κλήσεις → ενημέρωση CRM και προετοιμασία επόμενης ημέρας.','Δεν κρατάμε ψεύτικο pipeline. Ανενεργή ευκαιρία χρειάζεται review, αλλά καταγεγραμμένο future event με συμφωνημένη ημερομηνία δεν είναι εγκατάλειψη.']],
        ['Account development και προμήθειες',['Επιβεβαιώνουμε ικανοποίηση, άλλα sites, σχετικές ανάγκες, άλλους αρμόδιους και μελλοντικό follow-up. Cross-selling μόνο όπου υπάρχει πραγματική ανάγκη. Multi-threading: σχέση με περισσότερους από έναν σωστούς ανθρώπους.','Ίδια recurring υπηρεσία κρατά το ίδιο rate: cleaning 10% και στο δεύτερο/τρίτο έργο. Νέα υπηρεσία παίρνει το δικό της rate, π.χ. electrical 8%. Δεν δημιουργούμε αυτόματα νέο €80 επειδή επαναλαμβάνεται μια εργασία.','Account Owner και Lead Owner είναι διαφορετικές έννοιες. Αλλαγές ομάδας/ownership χρειάζονται τεκμηρίωση και δεν αλλάζουν αναδρομικά δεδουλευμένα. Team Leader override: πρόσθετο 10% της προμήθειας συνεργάτη, όχι της αξίας έργου, και ποτέ self-override.']]
    ],['Cleaning επαναλαμβάνεται το επόμενο έτος και προκύπτει ηλεκτρολογική εργασία.','Η ίδια υπηρεσία κρατά 10%. Η νέα ηλεκτρολογική παίρνει 8% στη δική της εγκεκριμένη βάση. Τεκμηριώνονται ξεχωριστά αντικείμενα και εισπράξεις.'],[
        ['5 qualified σε 20 συζητήσεις είναι…',['5%','20%','25%'],2,'5 / 20 = 25%.'],
        ['Recurring cleaning έχει…',['Το ίδιο 10% σύμφωνα με την εγκεκριμένη πολιτική','Υποχρεωτικά μισό rate','Πάντα νέο €80 χωρίς έλεγχο'],0,'Η επανάληψη δεν μειώνει το ποσοστό ούτε εγκρίνει αυτόματα lead fee.'],
        ['Override πάνω σε commission €3.000 είναι…',['€3.000 επιπλέον','€300 πρόσθετα για διαφορετικό έγκυρο Team Leader','€300 που αφαιρούνται από τον συνεργάτη'],1,'Είναι 10% της προμήθειας και δεν αφαιρείται από τον συνεργάτη.']
    ],10),
    ];
}
